package com.aadil.ecommerce.services;import com.aadil.ecommerce.dtos.ProductRequestDTO;import com.aadil.ecommerce.dtos.ProductResponseDTO;import com.aadil.ecommerce.entities.ProductEntity;import com.aadil.ecommerce.repositories.ProductRepository;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;@Service@RequiredArgsConstructorpublic class ProductService {    private final ProductRepository productRepository;   private ProductResponseDTO mapToProductDTO (ProductEntity productEntity){       return new ProductResponseDTO               (productEntity.getId()               ,productEntity.getProductName(),               productEntity.getDescription(),               productEntity.getPrice(),               productEntity.getStockQuantity(),               productEntity.getCategory(),               productEntity.getCreatedAt(),               productEntity.getUpdatedAt());   }   private ProductEntity mapToProductTable (ProductRequestDTO dto){       ProductEntity productEntity = new ProductEntity();       productEntity.setProductName(dto.getProductName());       productEntity.setDescription(dto.getDescription());       productEntity.setPrice(dto.getPrice());       productEntity.setStockQuantity(dto.getStockQuantity());       productEntity.setCategory(dto.getCategory());        return productEntity;   }   @Transactional   public ProductResponseDTO createProduct (ProductRequestDTO dto){       ProductEntity product = mapToProductTable(dto);       ProductEntity savedProduct = productRepository.save(product);       return mapToProductDTO(savedProduct);   }}